#Player:botV4
# 第9回 U-16旭川プログラミングコンテスト実行委員会「大会対戦用Bot」(old/botV4 の C# 版)を
# Python に移植したもの。乱数エンジンや細かいスコアリングは同一ではないが、
# 基本方針はそのまま踏襲している:
#   - 普段は同じ方向へ歩き続け、壁にぶつかるか4ターンに1回だけ方向を考え直す
#   - 方向を決め直すときは、安全なら歩く前にLookで覗いてから進む
#   - 相手を隣接マスに見つけたら斜め方向へ避ける。2回目以降に遭遇したら覗き見せず、
#     すぐ相手の方向にブロックを置いて仕留めにいく(元コードの「一回だけ許してあげる」仕様)
#   - アイテムは20ターンに1個までしか拾わない(拾いすぎて手詰まりにならないよう調整)
import random

DIRS = ["up", "down", "left", "right"]
IDX = {"up": 1, "left": 3, "right": 5, "down": 7}       # get_ready()の戻り値での隣接マスの位置
REV = {"up": "down", "down": "up", "left": "right", "right": "left"}
DIAG = {"up": ("left", "right"), "down": ("left", "right"), "left": ("up", "down"), "right": ("up", "down")}
# 9マスの各インデックス(中央4を除く)で相手を見つけたとき、除外すべき移動方向
ADJ_BLOCKED_DIRS = {
    0: ("left", "up"), 1: ("up",), 2: ("up", "right"),
    3: ("left",), 4: ("up", "down", "left", "right"), 5: ("right",),
    6: ("left", "down"), 7: ("down",), 8: ("down", "right"),
}
FLOOR, ENEMY, BLOCK, ITEM = 0, 1, 2, 3


def walk(d):
    return {"up": client.walk_up, "down": client.walk_down, "left": client.walk_left, "right": client.walk_right}[d]()


def look(d):
    return {"up": client.look_up, "down": client.look_down, "left": client.look_left, "right": client.look_right}[d]()


def search(d):
    return {"up": client.search_up, "down": client.search_down, "left": client.search_left, "right": client.search_right}[d]()


def put(d):
    return {"up": client.put_up, "down": client.put_down, "left": client.put_left, "right": client.put_right}[d]()


turn = 0
step_count = 0
item_count = 0
hotoke_face = 0          # 遭遇を一回だけ見逃す猶予カウンタ
safe = True
last_dir = None          # 直前に向いていた方向(歩き続ける基準)
last_was_look = False    # 直前の行動がLookだったか
last_look_saw_enemy = False

while True:
    turn += 1
    step_count += 1
    value = client.get_ready()

    movable = list(DIRS)
    action = None  # (種類, 方向) を決めたらここに入れる

    # ---- 周囲(8マス)に相手がいないかチェック -------------------------------------
    enemy_idxs = [i for i in range(9) if i != 4 and value[i] == ENEMY]
    ortho_enemy_dirs = [d for d, i in IDX.items() if i in enemy_idxs]

    if ortho_enemy_dirs:
        hotoke_face += 1
        d = ortho_enemy_dirs[0]
        if hotoke_face > 1:
            action = ("put", d)  # 二度目以降の遭遇は容赦なく仕留める
        else:
            a, b = DIAG[d]
            a_free = value[IDX[a]] != BLOCK
            b_free = value[IDX[b]] != BLOCK
            if a_free and b_free:
                action = ("walk", random.choice([a, b]))
            elif a_free:
                action = ("walk", a)
            elif b_free:
                action = ("walk", b)
            # 逃げ場が無ければ通常ロジックに任せる(actionはNoneのまま)

    for i in enemy_idxs:
        for rd in ADJ_BLOCKED_DIRS[i]:
            if rd in movable:
                movable.remove(rd)

    # ---- 隣接マスがブロックの方向を除外 -------------------------------------------
    for d, i in IDX.items():
        if value[i] == BLOCK and d in movable:
            movable.remove(d)

    # ---- アイテムは20ターンに1個まで ----------------------------------------------
    if item_count * 20 + 20 >= turn:
        item_dirs = [d for d in movable if value[IDX[d]] == ITEM]
        if item_dirs and len(item_dirs) == len(movable):
            item_dirs.remove(random.choice(item_dirs))  # 全滅させると詰むので1方向だけ残す
        for d in item_dirs:
            movable.remove(d)

    # ---- 通常ロジック(相手が原因のactionが決まっていないときだけ) -----------------
    if action is None:
        if last_dir is None:
            d = random.choice(movable) if movable else None
            action = ("walk", d) if d else None
        else:
            cmd_dir = last_dir
            if last_was_look and last_look_saw_enemy and safe and random.random() < 0.9:
                if len(movable) > 1 and cmd_dir in movable:
                    movable.remove(cmd_dir)
                safe = False
                step_count = -1  # 次のターンで強制的に方向を考え直す

            if cmd_dir not in movable or step_count % 4 == 0:
                step_count = 0
                if len(movable) == 0:
                    action = None
                elif len(movable) == 1:
                    action = ("look", movable[0])
                else:
                    rev = REV.get(cmd_dir)
                    if rev in movable and len(movable) > 1:
                        movable.remove(rev)
                    if len(movable) > 1:
                        movable.remove(random.choice(movable))
                    chosen = movable[0] if len(movable) == 1 else random.choice(movable)
                    if safe:
                        action = ("look", chosen)
                    else:
                        action = ("walk", chosen)
                        safe = True
            else:
                action = ("walk", cmd_dir)

    # ---- それでも決まらなければランダムにlook/searchして様子を見る -----------------
    if action is None:
        action = (random.choice(["look", "search"]), random.choice(DIRS))

    kind, d = action

    # ---- 歩いた先がアイテムなら取得数をカウント(20ターン制限の計算に使う) ---------
    if kind == "walk" and value[IDX[d]] == ITEM:
        item_count += 1

    if kind == "walk":
        value = walk(d)
        last_dir, last_was_look = d, False
    elif kind == "look":
        value = look(d)
        last_dir, last_was_look = d, True
        last_look_saw_enemy = ENEMY in value
    elif kind == "search":
        value = search(d)
        last_dir, last_was_look = d, True
        last_look_saw_enemy = ENEMY in value
    else:
        value = put(d)
        last_dir, last_was_look = d, False
